#include <stdio.h>
#include <stdlib.h>

static long long a[1600];

static int cmp_ll(const void *x, const void *y) {
    long long u = *(const long long *)x;
    long long v = *(const long long *)y;
    if (u < v) return -1;
    if (u > v) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) {
        long long v;
        if (scanf("%lld", &v) != 1) v = 0;
        a[i] = v;
    }
    qsort(a, n, sizeof(long long), cmp_ll);

    /* Para cada par (i, j) com a[i] <= a[j] (menores lados), conta os k > j
       com a[k] < a[i] + a[j] (maior lado). Como a[i] + a[j] nao decresce com j,
       o ponteiro r (primeiro indice invalido) so avanca: O(N^2) total. */
    long long total = 0;
    for (int i = 0; i < n; i++) {
        int r = i + 2;
        for (int j = i + 1; j < n; j++) {
            if (r < j + 1) r = j + 1;
            long long lim = a[i] + a[j];
            while (r < n && a[r] < lim) r++;
            total += r - j - 1;
        }
    }
    printf("%lld\n", total);
    return 0;
}
